<?php
 namespace Pterodactyl\Http\Controllers\Api\Client\Servers; use Illuminate\Http\JsonResponse; use Pterodactyl\Exceptions\DisplayException; use Pterodactyl\Http\Controllers\Api\Client\ClientApiController; use Pterodactyl\Http\Requests\Api\Client\Servers\Support\GetSupportRequest; use Pterodactyl\Http\Requests\Api\Client\Servers\Support\ManageSupportRequest; use Pterodactyl\Http\Requests\Api\Client\Servers\Support\SendMessageRequest; use Pterodactyl\Http\Requests\Api\Client\Servers\Support\StoreSupportRequest; use Pterodactyl\Models\Dezerx\StaffRequest; use Pterodactyl\Models\Server; use Pterodactyl\Models\User; use Pterodactyl\Services\Dezerx\Staff\Staff; use Pterodactyl\Services\Dezerx\Staff\StaffChat; use Pterodactyl\Services\Dezerx\Staff\StaffPresenter; use Pterodactyl\Services\Dezerx\Staff\StaffRequests; use Pterodactyl\Services\Dezerx\Staff\StaffReviews; use Symfony\Component\HttpKernel\Exception\NotFoundHttpException; class StaffSupportController extends ClientApiController { private const HISTORY = 25; public function __construct(private StaffRequests $requests) { parent::__construct(); } public function index(GetSupportRequest $request, Server $server): JsonResponse { $requests = $this->requests->forServer($server)->limit(self::HISTORY)->get(); return new JsonResponse(StaffPresenter::serverState($server, $request->user(), $requests)); } public function store(StoreSupportRequest $request, Server $server): JsonResponse { if ($request->has('auto_accept')) { Staff::rememberAutoAccept($request->user(), $request->boolean('auto_accept')); } $created = $this->requests->open($server, $request->user(), [ 'direction' => StaffRequest::DIRECTION_OWNER, 'reason' => (string) $request->input('reason'), 'scope' => (string) $request->input('scope'), 'username' => (string) $request->input('username', ''), 'open_ended' => $request->boolean('open_ended'), 'duration_minutes' => $request->input('duration_minutes'), 'permissions' => $request->input('permissions', []), ]); return $this->single($created, $request->user()); } public function allow(ManageSupportRequest $request, Server $server, string $uuid): JsonResponse { $found = $this->find($server, $uuid); if ($found->isClaimed()) { $updated = $this->requests->confirm($found, $request->user()); } elseif ($found->isPending() && $found->direction === StaffRequest::DIRECTION_STAFF) { $updated = $this->requests->approve($found, $request->user()); } else { throw new DisplayException('There is nobody waiting to be let in on that request.'); } return $this->single($updated, $request->user()); } public function deny(ManageSupportRequest $request, Server $server, string $uuid): JsonResponse { $updated = $this->requests->deny( $this->find($server, $uuid), $request->user(), (string) $request->input('reason', '') ); return $this->single($updated, $request->user()); } public function cancel(ManageSupportRequest $request, Server $server, string $uuid): JsonResponse { $updated = $this->requests->cancel($this->find($server, $uuid), $request->user()); return $this->single($updated, $request->user()); } public function revoke(ManageSupportRequest $request, Server $server, string $uuid): JsonResponse { $updated = $this->requests->revoke( $this->find($server, $uuid), $request->user(), (string) $request->input('reason', '') ); return $this->single($updated, $request->user()); } public function extend(ManageSupportRequest $request, Server $server, string $uuid): JsonResponse { $minutes = $request->input('minutes'); $updated = $this->requests->grantExtension( $this->find($server, $uuid), $request->user(), $minutes === null ? null : (int) $minutes ); return $this->single($updated, $request->user()); } public function refuseExtension(ManageSupportRequest $request, Server $server, string $uuid): JsonResponse { $updated = $this->requests->denyExtension($this->find($server, $uuid), $request->user()); return $this->single($updated, $request->user()); } public function trim(ManageSupportRequest $request, Server $server, string $uuid): JsonResponse { $updated = $this->requests->trim( $this->find($server, $uuid), $request->user(), $request->input('permissions', []) ); return $this->single($updated, $request->user()); } public function messages(GetSupportRequest $request, Server $server, string $uuid): JsonResponse { $found = $this->find($server, $uuid); $user = $request->user(); if (!StaffChat::canRead($found, $user)) { throw new NotFoundHttpException(); } $after = (int) $request->query('after', '0'); $before = (int) $request->query('before', '0'); $messages = StaffChat::messages($found, max(0, $after), max(0, $before)); if ($after === 0 && $before === 0) { StaffChat::markRead($found, $user); } $first = $messages->first(); return new JsonResponse([ 'messages' => StaffPresenter::messages($messages, $user, $found), 'canPost' => StaffChat::canWrite($found, $user), 'more' => $after === 0 && $first !== null && StaffChat::hasOlder($found, (int) $first->id), ]); } public function send(SendMessageRequest $request, Server $server, string $uuid): JsonResponse { $user = $request->user(); $found = $this->find($server, $uuid); $message = StaffChat::post($found, $user, (string) $request->input('body')); return new JsonResponse(['message' => StaffPresenter::message($message, $user, $found)]); } public function autoAccept(ManageSupportRequest $request, Server $server): JsonResponse { $value = $request->boolean('value'); Staff::rememberAutoAccept($request->user(), $value); return new JsonResponse(['autoAccept' => $value]); } public function feedback(ManageSupportRequest $request, Server $server, string $uuid): JsonResponse { $data = $request->validate([ 'mood' => ['required', 'string', 'max:8'], 'note' => ['sometimes', 'nullable', 'string', 'max:1000'], ]); $user = $request->user(); StaffReviews::leave( $this->find($server, $uuid), $user, (string) $data['mood'], (string) ($data['note'] ?? '') ); return $this->single($this->find($server, $uuid), $user); } private function find(Server $server, string $uuid): StaffRequest { $found = StaffRequest::query() ->where('server_id', $server->id) ->where('uuid', $uuid) ->first(); if ($found === null) { throw new NotFoundHttpException(); } return $found; } private function single(StaffRequest $request, User $viewer): JsonResponse { return new JsonResponse(['request' => StaffPresenter::request($request->refresh(), $viewer, true)]); } } 